// Collect everything the brief needs into one compact prompt.
const safe = (name) => { try { return $(name).all().map(i => i.json).filter(j => Object.keys(j).length); } catch { return []; } };

const events = safe("Today's calendar").map(e => `- ${e.start?.dateTime || e.start?.date || ''} ${e.summary || '(no title)'}${e.location ? ' @ ' + e.location : ''}`);
const mail = safe('Unread email (24h)').slice(0, 25).map(m => `- From ${m.From || m.from?.text || '?'}: ${m.Subject || m.subject || '(no subject)'} | ${(m.snippet || '').slice(0, 200)}`);
const news = safe('Industry news (RSS)').slice(0, 8).map(n => `- ${n.title} (${n.link})`);

const today = $today.toFormat('cccc d LLLL yyyy');
const prompt = [
  `Today is ${today}. Write my morning brief.`,
  '', 'CALENDAR:', events.join('\n') || '- nothing scheduled',
  '', 'UNREAD EMAIL:', mail.join('\n') || '- inbox zero',
  '', 'NEWS:', news.join('\n') || '- no new items',
].join('\n');

return [{ json: { prompt } }];

