// The response holds content blocks; the brief is in the text block(s).
const res = $input.first().json;
let text;
if (res.stop_reason === 'refusal') {
  text = 'Daily brief: the model declined today\'s input. Check the n8n execution log.';
} else {
  text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim() || 'Daily brief: empty response.';
}
// Telegram messages max out at 4096 characters.
const chunks = [];
for (let i = 0; i < text.length; i += 4000) chunks.push({ json: { text: text.slice(i, i + 4000) } });
return chunks;
